/// A numeral form: which cell of its declension.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Cell {
    /// A noun in a case and number.
    Form(crate::Case, crate::Number),
}

impl Cell {
    /// Its place in a paradigm.
    pub const fn index(self) -> usize {
        use crate::Case::*;
        use crate::Number::*;
        let cell = match self {
            Cell::Form(Nominative, Singular) => cell::NOM_SG,
            Cell::Form(Nominative, Plural) => cell::NOM_PL,
            Cell::Form(Genitive, Singular) => cell::GEN_SG,
            Cell::Form(Genitive, Plural) => cell::GEN_PL,
            Cell::Form(Partitive, Singular) => cell::PAR_SG,
            Cell::Form(Partitive, Plural) => cell::PAR_PL,
            Cell::Form(Inessive, Singular) => cell::INE_SG,
            Cell::Form(Inessive, Plural) => cell::INE_PL,
            Cell::Form(Elative, Singular) => cell::ELA_SG,
            Cell::Form(Elative, Plural) => cell::ELA_PL,
            Cell::Form(Illative, Singular) => cell::ILL_SG,
            Cell::Form(Illative, Plural) => cell::ILL_PL,
            Cell::Form(Adessive, Singular) => cell::ADE_SG,
            Cell::Form(Adessive, Plural) => cell::ADE_PL,
            Cell::Form(Ablative, Singular) => cell::ABL_SG,
            Cell::Form(Ablative, Plural) => cell::ABL_PL,
            Cell::Form(Allative, Singular) => cell::ALL_SG,
            Cell::Form(Allative, Plural) => cell::ALL_PL,
            Cell::Form(Essive, Singular) => cell::ESS_SG,
            Cell::Form(Essive, Plural) => cell::ESS_PL,
            Cell::Form(Translative, Singular) => cell::TRA_SG,
            Cell::Form(Translative, Plural) => cell::TRA_PL,
            Cell::Form(Abessive, Singular) => cell::ABE_SG,
            Cell::Form(Abessive, Plural) => cell::ABE_PL,
            Cell::Form(Instructive, Singular) => cell::INS_SG,
            Cell::Form(Instructive, Plural) => cell::INS_PL,
            Cell::Form(Comitative, Singular) => cell::COM_SG,
            Cell::Form(Comitative, Plural) => cell::COM_PL,
        };
        cell as usize
    }
}

impl From<(crate::Case, crate::Number)> for Cell {
    fn from((case, number): (crate::Case, crate::Number)) -> Self {
        Cell::Form(case, number)
    }
}

/// A numeral to inflect: its lemma, and what you know of it. The more you
/// tell, the surer its forms.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Numeral<'w> {
    lemma: &'w str,
    given: Vec<(usize, &'w str)>,
}

impl<'w> Numeral<'w> {
    /// The numeral `lemma`, as the dictionary writes it.
    #[must_use]
    pub fn new(lemma: &'w str) -> Self {
        Numeral {
            lemma,
            given: Vec::new(),
        }
    }

    /// One of its forms you know (a principal part): readings that disagree
    /// with it are dropped.
    #[must_use]
    pub fn given(mut self, cell: impl Into<Cell>, form: &'w str) -> Self {
        self.given.push((cell.into().index(), form));
        self
    }

    fn known(&self) -> Known<'_> {
        Known {
            forms: &self.given,
            inherent: &[],
            full: false,
        }
    }

    /// Its likeliest form in `cell`.
    #[must_use]
    pub fn form(&self, cell: impl Into<Cell>) -> String {
        GRAMMAR.best(self.lemma, cell.into().index(), &self.known())
    }

    /// Every form it may have in `cell`, likeliest first, each with its
    /// probability and why.
    #[must_use]
    pub fn candidates(&self, cell: impl Into<Cell>) -> Vec<Candidate<'static>> {
        GRAMMAR.candidates(self.lemma, cell.into().index(), &self.known())
    }

    /// The declensions it may follow, likeliest first, each with its probability
    /// and why.
    #[must_use]
    pub fn declension(&self) -> Vec<Reading<'static, 'static, Declension>> {
        GRAMMAR.readings(self.lemma, &self.known())
    }
}
